// ── Tree-walking interpreter for a tiny expression language ───────
// Supports: number literals, variables, +, -, *, function calls

class Interpreter {
  constructor() {
    this.env = {}; // variable store
  }

  eval(node) {
    switch (node.type) {
      case 'Literal':
        return node.value;

      case 'Identifier':
        if (!(node.name in this.env))
          throw new ReferenceError(`Undefined: ${node.name}`);
        return this.env[node.name];

      case 'BinaryExpression': {
        const l = this.eval(node.left);
        const r = this.eval(node.right);
        switch (node.operator) {
          case '+': return l + r;
          case '-': return l - r;
          case '*': return l * r;
          case '/': if (r === 0) throw new Error('Division by zero'); return l / r;
          default: throw new Error(`Unknown operator: ${node.operator}`);
        }
      }

      case 'VariableDeclaration':
        this.env[node.name] = this.eval(node.init);
        return undefined;

      case 'Program':
        return node.body.reduce((_, stmt) => this.eval(stmt), undefined);

      default:
        throw new Error(`Unknown node type: ${node.type}`);
    }
  }
}

// AST for:  let area = 6 * 7
const program = {
  type: 'Program',
  body: [
    { type: 'VariableDeclaration', name: 'area',
      init: { type: 'BinaryExpression', operator: '*',
               left:  { type: 'Literal', value: 6 },
               right: { type: 'Literal', value: 7 } } },
    { type: 'Identifier', name: 'area' }
  ]
};

const interp = new Interpreter();
const result = interp.eval(program);
console.log('area =', result); // area = 42
console.log('env:', interp.env); // env: { area: 42 }

// ── Bytecode concept: compile AST to a stack-machine instruction list ──
function compileToBytecode(node) {
  const instructions = [];
  function emit(op, arg) { instructions.push(arg !== undefined ? [op, arg] : [op]); }

  function compile(n) {
    switch (n.type) {
      case 'Literal':           emit('PUSH', n.value); break;
      case 'Identifier':        emit('LOAD', n.name);  break;
      case 'BinaryExpression':
        compile(n.left);
        compile(n.right);
        emit(n.operator === '+' ? 'ADD' :
             n.operator === '-' ? 'SUB' :
             n.operator === '*' ? 'MUL' : 'DIV');
        break;
      default: throw new Error(`Cannot compile: ${n.type}`);
    }
  }

  compile(node);
  return instructions;
}

// Compile expression: 6 * 7
const exprNode = {
  type: 'BinaryExpression', operator: '*',
  left:  { type: 'Literal', value: 6 },
  right: { type: 'Literal', value: 7 }
};
const bytecode = compileToBytecode(exprNode);
console.log(bytecode);
// [ ['PUSH', 6], ['PUSH', 7], ['MUL'] ]

// ── Stack VM to execute bytecode ─────────────────────────────────
function runBytecode(instructions, env) {
  const stack = [];
  for (const [op, arg] of instructions) {
    if (op === 'PUSH') stack.push(arg);
    else if (op === 'LOAD') stack.push(env[arg]);
    else if (op === 'ADD') { const b = stack.pop(), a = stack.pop(); stack.push(a + b); }
    else if (op === 'SUB') { const b = stack.pop(), a = stack.pop(); stack.push(a - b); }
    else if (op === 'MUL') { const b = stack.pop(), a = stack.pop(); stack.push(a * b); }
  }
  return stack[0];
}
console.log('bytecode result:', runBytecode(bytecode, {})); // 42

